const promotionForm=document.createElement('section');promotionForm.className='promotion-panel';promotionForm.innerHTML=`<div><span class="eyebrow">GROW YOUR LOCAL REACH</span><h2>Promote your wholesale business</h2><p class="muted">Get a labelled sponsored placement in relevant market searches. Vendor access stays free.</p></div><div class="promotion-plan"><span>Weekly spotlight</span><strong>₹199 <small>/ 7 days</small></strong><p>Illustrative price · Demo checkout</p></div><form id="promotionForm"><label>Promote in<select id="promotionCategory"><option value="All categories">All categories</option>${productCategories.map(([c])=>`<option value="${safe(c)}">${safe(c)}</option>`).join('')}</select></label><label class="promotion-consent"><input id="promotionConsent" type="checkbox" required><span>I understand this is a demo. No money will be charged.</span></label><button id="promotionBuy" class="primary">Simulate purchase & activate →</button></form><div id="promotionActive" hidden><strong>Demo promotion active</strong><p id="promotionExpiry"></p><button id="promotionStop" type="button" class="orderbtn">Stop demo promotion</button></div><p class="promotion-note">Sponsored placement never changes reviews, trust ratings or price and distance sorting.</p><p id="promotionError" class="auth-error" role="alert"></p>`;
$('#supplier').append(promotionForm);
async function refreshPromotion(){if(currentUser?.role!=='wholesaler')return;const {promotion}=await api('/promotions');$('#promotionForm').hidden=Boolean(promotion);$('#promotionActive').hidden=!promotion;if(promotion){$('#promotionExpiry').textContent=`${promotion.category} · ${'Ends:'} ${new Date(promotion.ends).toLocaleString(document.documentElement.lang+'-IN')}`}translateUI()}
$('#promotionForm').onsubmit=async e=>{e.preventDefault();const button=$('#promotionBuy');button.disabled=true;$('#promotionError').textContent='';try{await api('/promotions/demo-checkout',{method:'POST',body:JSON.stringify({plan:'weekly',category:$('#promotionCategory').value,demoConfirmed:$('#promotionConsent').checked})});await Promise.all([refreshPromotion(),refreshMarket()]);toast('Demo promotion activated. No money was charged.')}catch(error){$('#promotionError').textContent=error.message;translateUI()}finally{button.disabled=false}};
$('#promotionStop').onclick=async()=>{const button=$('#promotionStop');button.disabled=true;try{await api('/promotions/stop',{method:'POST',body:'{}'});await Promise.all([refreshPromotion(),refreshMarket()]);toast('Demo promotion stopped.')}catch(error){$('#promotionError').textContent=error.message;translateUI()}finally{button.disabled=false}};
const supplierNav=document.querySelector('[data-page="supplier"]'),supplierShow=supplierNav.onclick;supplierNav.onclick=()=>{supplierShow();refreshPromotion().catch(error=>{$('#promotionError').textContent=error.message;translateUI()})};

